331	fn parse_closing_tag(p: &mut HtmlParser) -> ParsedSyntax {
332	    if !p.at(T![<]) || !p.nth_at(1, T![/]) {
333	        return Absent;
334	    }
335	    let m = p.start();
336	    p.bump_with_context(T![<], inside_tag_context(p));
337	    p.bump_with_context(T![/], inside_tag_context(p));
338	    let should_be_self_closing = VOID_ELEMENTS
339	        .iter()
340	        .any(|tag| tag.eq_ignore_ascii_case(p.cur_text()))
341	        && !is_possible_component(p, p.cur_text());
342	    if should_be_self_closing {
343	        p.error(void_element_should_not_have_closing_tag(p, p.cur_range()).into_diagnostic(p));
344	    }
345	    let _name = parse_any_tag_name(p);
346	
347	    // There shouldn't be any attributes in a closing tag.
348	    while p.at(HTML_LITERAL) || p.at(T!["{{"]) || p.at(T!["}}"]) {
349	        p.error(closing_tag_should_not_have_attributes(p, p.cur_range()));
350	        p.bump_remap_with_context(HTML_BOGUS, HtmlLexContext::InsideTag);
351	    }
352	    p.expect(T![>]);
353	    Present(m.complete(p, HTML_CLOSING_ELEMENT))
354	}
