/// Peek whether the parser is positioned at a closing tag (`</name>`) whose name
/// is a void element (e.g. `</br>`, `</input>`).
///
/// Determining the tag name requires lexing the name in an inside-tag context,
/// so this uses a checkpoint to inspect the name and then rewinds, leaving the
/// parser exactly where it started.
fn at_void_element_closing_tag(p: &mut HtmlParser) -> bool {
    if !p.at(T![<]) || !p.nth_at(1, T![/]) {
        return false;
    }
    let checkpoint = p.checkpoint();
    p.bump_with_context(T![<], inside_tag_context(p));
    p.bump_with_context(T![/], inside_tag_context(p));
    let is_void = VOID_ELEMENTS
        .iter()
        .any(|tag| tag.eq_ignore_ascii_case(p.cur_text()))
        && !is_possible_component(p, p.cur_text());
    p.rewind(checkpoint);
    is_void
}

